insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('el-papel-de-las-redes-de-apoyo-en-momentos-de-dificultad-como-se','sociedad',array['salud']::text[],'El papel de las redes de apoyo en momentos de dificultad: cómo se organiza una comunidad para ayudar a una familia','Estudia cómo se activan las redes de apoyo familiares, vecinales y comunitarias cuando una familia atraviesa una situación difícil, qué tipos de ayuda circulan y qué ayuda a que sean efectivas.','Investigación','3 a 4 semanas',24,array['Redes de apoyo','Solidaridad']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion entrevistas. analisis cualitativo. sintesis. redaccion sensible. una guia de conversacion. un editor de diagramas. un editor de documentos.',$a49sld${"id": "el-papel-de-las-redes-de-apoyo-en-momentos-de-dificultad-como-se", "area": "sociedad", "areas2": ["salud"], "titulo": "El papel de las redes de apoyo en momentos de dificultad: cómo se organiza una comunidad para ayudar a una familia", "resumen": "Estudia cómo se activan las redes de apoyo familiares, vecinales y comunitarias cuando una familia atraviesa una situación difícil, qué tipos de ayuda circulan y qué ayuda a que sean efectivas.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Redes de apoyo", "Solidaridad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Cuando una familia enfrenta una enfermedad, un desempleo o una pérdida, suele recibir ayuda de vecinos, amigos o grupos comunitarios: comida, dinero, compañía, información. Esa ayuda no siempre está organizada ni llega a todos por igual.", "Entender cómo funciona permite fortalecerla y reconocer su valor."], "desarrollar": ["Con conversaciones voluntarias y anónimas con personas que han recibido o brindado ayuda comunitaria, sin pedir detalles de la situación, describe los tipos de ayuda, cómo se organizó y qué la hizo útil. Complementa con lecturas.", "Agrupa las ayudas en categorías, como económica, material, emocional e informativa, y resume qué prácticas facilitaron que fuera oportuna y respetuosa. Elabora una guía de buenas prácticas para organizar apoyo comunitario."], "ampliaciones": [{"titulo": "Quién queda sin ayuda", "aporta": "analiza qué personas no cuentan con redes."}, {"titulo": "Ayuda que no ayuda", "aporta": "identifica apoyos que pueden resultar incómodos o dañinos."}, {"titulo": "Mapa de red", "aporta": "dibuja una red de apoyo ficticia y sus conexiones."}], "objetivos": ["Describir tipos de ayuda comunitaria.", "Identificar prácticas efectivas.", "Reconocer vacíos.", "Elaborar una guía."], "habilidades": ["Entrevistas.", "Análisis cualitativo.", "Síntesis.", "Redacción sensible."], "herramientas": ["Una guía de conversación.", "Un editor de diagramas.", "Un editor de documentos."], "lineamientos": ["Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "No preguntes por detalles de situaciones difíciles ni recojas datos que identifiquen a familias."], "otroSector": "El mismo estudio sirve para analizar cómo se organiza el apoyo entre colegas ante una emergencia."}$a49sld$::jsonb,59),
('como-se-organizan-las-redes-de-apoyo-informal-entre-vecinos-y-qu','sociedad',array['ciudades']::text[],'Cómo se organizan las redes de apoyo informal entre vecinos y qué experiencias de cooperación existen','Documenta cómo cooperan los vecinos de forma informal, como cuidando niños, compartiendo herramientas o vigilándose, y qué hace que esa cooperación se mantenga o se debilite.','Investigación','3 a 4 semanas',24,array['Cooperación vecinal','Redes informales']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion observacion. entrevistas. mapeo. redaccion. una guia de conversacion. un editor de mapas. un editor de documentos.',$a50sld${"id": "como-se-organizan-las-redes-de-apoyo-informal-entre-vecinos-y-qu", "area": "sociedad", "areas2": ["ciudades"], "titulo": "Cómo se organizan las redes de apoyo informal entre vecinos y qué experiencias de cooperación existen", "resumen": "Documenta cómo cooperan los vecinos de forma informal, como cuidando niños, compartiendo herramientas o vigilándose, y qué hace que esa cooperación se mantenga o se debilite.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Cooperación vecinal", "Redes informales"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["En muchas calles y barrios los vecinos se ayudan sin que nadie lo organice: se prestan cosas, cuidan a los niños, avisan de peligros. Esa cooperación informal sostiene la vida diaria, pero casi nunca se registra ni se valora.", "Documentarla muestra la fuerza de la comunidad y cómo cuidarla."], "desarrollar": ["Con permiso y de manera voluntaria, conversa con cinco a diez vecinos de una zona sobre qué formas de ayuda mutua existen, con quién y desde cuándo, qué la facilita y qué la dificulta. Observa los lugares de encuentro con respeto.", "Dibuja un mapa de ayudas, clasifica los tipos de cooperación y explica qué condiciones, como tiempo compartido, confianza o espacios comunes, parecen sostenerla."], "ampliaciones": [{"titulo": "Rutinas de ayuda", "aporta": "identifica ayudas diarias y ayudas ocasionales."}, {"titulo": "Nuevos vecinos", "aporta": "analiza cómo se integran a las redes."}, {"titulo": "Cuando se rompe", "aporta": "analiza qué ocurre cuando hay conflictos entre vecinos."}], "objetivos": ["Documentar formas de cooperación.", "Mapearlas.", "Identificar condiciones.", "Presentar los hallazgos."], "habilidades": ["Observación.", "Entrevistas.", "Mapeo.", "Redacción."], "herramientas": ["Una guía de conversación.", "Un editor de mapas.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No identifiques viviendas ni personas en tu mapa: usa categorías generales."], "otroSector": "El mismo trabajo sirve para analizar redes de colaboración entre colegas o emprendedores."}$a50sld$::jsonb,60),
('que-hace-que-una-comunidad-sea-mas-unida','sociedad',array[]::text[],'¿Qué hace que una comunidad sea más unida?','Revisa qué condiciones se asocian con comunidades más cohesionadas, como espacios compartidos, confianza, participación o proyectos comunes, y compara ejemplos de comunidades distintas.','Investigación','3 semanas',22,array['Cohesión social','Comunidad']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion lectura de estudios. analisis comparativo. sintesis. propuestas de mejora. fuentes academicas y de divulgacion. un editor de esquemas. un editor de documentos.',$a51sld${"id": "que-hace-que-una-comunidad-sea-mas-unida", "area": "sociedad", "areas2": [], "titulo": "¿Qué hace que una comunidad sea más unida?", "resumen": "Revisa qué condiciones se asocian con comunidades más cohesionadas, como espacios compartidos, confianza, participación o proyectos comunes, y compara ejemplos de comunidades distintas.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Cohesión social", "Comunidad"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Hay barrios y grupos donde la gente se conoce y se apoya, y otros donde cada quien vive aparte. La cohesión no depende de la suerte: hay condiciones que la favorecen y otras que la debilitan.", "Conocerlas ayuda a tomar decisiones para fortalecer la unión."], "desarrollar": ["Con estudios y experiencias documentadas, reúne los factores que se mencionan como favorables a la cohesión, como confianza, espacios públicos, tiempo compartido, reglas claras y objetivos comunes, y organízalos en un esquema.", "Aplica el esquema a dos comunidades ficticias o públicas, compara y propón cinco acciones sencillas para fortalecer la unión en una comunidad concreta, indicando qué factor atacan."], "ampliaciones": [{"titulo": "Indicadores", "aporta": "propón cómo medir la cohesión con preguntas simples."}, {"titulo": "Comunidades en línea", "aporta": "compara con grupos digitales."}, {"titulo": "Efecto de un evento", "aporta": "analiza cómo una fiesta o una crisis cambia la unión."}], "objetivos": ["Reunir factores de cohesión.", "Aplicarlos a casos.", "Comparar comunidades.", "Proponer acciones."], "habilidades": ["Lectura de estudios.", "Análisis comparativo.", "Síntesis.", "Propuestas de mejora."], "herramientas": ["Fuentes académicas y de divulgación.", "Un editor de esquemas.", "Un editor de documentos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo análisis sirve para entender la cohesión en equipos de trabajo."}$a51sld$::jsonb,61),
('mapeando-los-recursos-de-una-comunidad-personas-saberes-y-espaci','sociedad',array['ciudades']::text[],'Mapeando los recursos de una comunidad: personas, saberes y espacios disponibles','Haz un mapa de lo que una comunidad ya tiene: personas con habilidades, saberes, espacios y organizaciones, para ver con qué recursos cuenta y cómo conectarlos, en lugar de partir solo de sus carencias.','Prototipo','4 semanas',26,array['Mapeo comunitario','Recursos']::text[],array['crear','investigar']::text[],'propios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion mapeo comunitario. diseno de fichas. visualizacion. planificacion. una ficha de registro. un editor de mapas. hoja de calculo.',$a52sld${"id": "mapeando-los-recursos-de-una-comunidad-personas-saberes-y-espaci", "area": "sociedad", "areas2": ["ciudades"], "titulo": "Mapeando los recursos de una comunidad: personas, saberes y espacios disponibles", "resumen": "Haz un mapa de lo que una comunidad ya tiene: personas con habilidades, saberes, espacios y organizaciones, para ver con qué recursos cuenta y cómo conectarlos, en lugar de partir solo de sus carencias.", "tipo": "Prototipo", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Mapeo comunitario", "Recursos"], "intencion": ["crear", "investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Los diagnósticos comunitarios suelen centrarse en lo que falta. Pero toda comunidad tiene recursos: gente con oficios, locales, saberes, redes y ganas de colaborar. Si no se visibilizan, no se aprovechan.", "Mapearlos permite pensar proyectos desde lo que ya existe."], "desarrollar": ["Diseña una ficha para registrar recursos de una comunidad, como personas con habilidades que quieren compartir, espacios, organizaciones, saberes y herramientas. Aplícala con permiso en una zona pequeña y organiza lo recogido en categorías.", "Dibuja un mapa o directorio de los recursos, identifica conexiones posibles, como quién podría enseñar a quién, y propón tres iniciativas que se podrían hacer solo con lo que ya hay."], "ampliaciones": [{"titulo": "Banco de habilidades", "aporta": "arma una lista de lo que las personas pueden ofrecer."}, {"titulo": "Recursos subutilizados", "aporta": "identifica espacios o saberes poco usados."}, {"titulo": "Actualización", "aporta": "define cómo mantener el mapa al día."}], "objetivos": ["Diseñar una ficha de recursos.", "Recoger información con permiso.", "Mapear y categorizar.", "Proponer iniciativas."], "habilidades": ["Mapeo comunitario.", "Diseño de fichas.", "Visualización.", "Planificación."], "herramientas": ["Una ficha de registro.", "Un editor de mapas.", "Hoja de cálculo."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Registra solo lo que las personas quieran compartir y no publiques datos de contacto sin permiso."], "otroSector": "El mismo mapeo sirve para identificar capacidades dentro de una empresa o una universidad."}$a52sld$::jsonb,62),
('iniciativas-que-generan-impacto-social-positivo-que-tienen-en-co','sociedad',array['negocios']::text[],'Iniciativas que generan impacto social positivo: ¿qué tienen en común?','Analiza tres a cinco iniciativas sociales con resultados documentados y busca qué prácticas comparten, para extraer lecciones que otros grupos puedan aplicar.','Análisis','3 a 4 semanas',24,array['Impacto social','Buenas prácticas']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion analisis de informes. comparacion. sintesis. redaccion. informes publicos. hoja de calculo. un editor de documentos.',$a53sld${"id": "iniciativas-que-generan-impacto-social-positivo-que-tienen-en-co", "area": "sociedad", "areas2": ["negocios"], "titulo": "Iniciativas que generan impacto social positivo: ¿qué tienen en común?", "resumen": "Analiza tres a cinco iniciativas sociales con resultados documentados y busca qué prácticas comparten, para extraer lecciones que otros grupos puedan aplicar.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Impacto social", "Buenas prácticas"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Hay iniciativas pequeñas que logran cambios reales y otras grandes que no. Rara vez se estudia qué hicieron distinto: cómo se organizaron, a quién escucharon, cómo midieron y cómo se mantuvieron.", "Aprender de ellas evita que cada grupo empiece de cero."], "desarrollar": ["Con informes públicos, reúne cinco iniciativas sociales con resultados documentados. Para cada una resume el problema, la acción, quiénes participaron, cuánto duró, cómo se financió y qué resultados mostró.", "Compara las iniciativas, identifica prácticas comunes, como escuchar a los beneficiarios, medir resultados o alianzas, y escribe un resumen de diez lecciones con ejemplos."], "ampliaciones": [{"titulo": "Fracasos", "aporta": "analiza una iniciativa que no funcionó y por qué."}, {"titulo": "Escala", "aporta": "estudia cómo crecieron iniciativas pequeñas."}, {"titulo": "Lecciones locales", "aporta": "adapta las lecciones a un problema de tu zona."}], "objetivos": ["Reunir iniciativas documentadas.", "Compararlas.", "Extraer prácticas comunes.", "Redactar lecciones."], "habilidades": ["Análisis de informes.", "Comparación.", "Síntesis.", "Redacción."], "herramientas": ["Informes públicos.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Cita las fuentes y no atribuyas resultados que los informes no respalden."], "otroSector": "El mismo análisis sirve para extraer lecciones de proyectos de responsabilidad social empresarial."}$a53sld$::jsonb,63),
('analizando-la-colaboracion-entre-distintos-grupos-de-una-comunid','sociedad',array['derecho']::text[],'Analizando la colaboración entre distintos grupos de una comunidad','Estudia cómo colaboran, o no, grupos distintos de una comunidad, como juntas vecinales, colegios, iglesias o clubes, y qué hace que trabajen juntos o se mantengan separados.','Análisis','3 semanas',22,array['Colaboración','Alianzas']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion mapeo de actores. entrevistas. analisis. redaccion. una guia de conversacion. un editor de diagramas. un editor de documentos.',$a54sld${"id": "analizando-la-colaboracion-entre-distintos-grupos-de-una-comunid", "area": "sociedad", "areas2": ["derecho"], "titulo": "Analizando la colaboración entre distintos grupos de una comunidad", "resumen": "Estudia cómo colaboran, o no, grupos distintos de una comunidad, como juntas vecinales, colegios, iglesias o clubes, y qué hace que trabajen juntos o se mantengan separados.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Colaboración", "Alianzas"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["En una comunidad conviven muchos grupos con intereses y formas de trabajar diferentes. A veces colaboran en un proyecto común y otras se ignoran o compiten, aun cuando comparten problemas.", "Entender los puentes y las barreras entre grupos permite fomentar alianzas útiles."], "desarrollar": ["Identifica de cuatro a seis grupos de una comunidad y, con permiso, pregunta a sus integrantes con quién colaboran, para qué y qué dificulta trabajar con otros. Dibuja un mapa de relaciones.", "Analiza qué proyectos lograron juntar a varios grupos, qué factores lo permitieron y propón dos oportunidades de colaboración que hoy no se aprovechan."], "ampliaciones": [{"titulo": "Intermediarios", "aporta": "identifica personas o grupos que conectan a otros."}, {"titulo": "Intereses comunes", "aporta": "busca temas que unan a varios grupos."}, {"titulo": "Espacio de coordinación", "aporta": "propón una reunión periódica entre grupos."}], "objetivos": ["Identificar grupos.", "Mapear relaciones.", "Detectar barreras y puentes.", "Proponer oportunidades."], "habilidades": ["Mapeo de actores.", "Entrevistas.", "Análisis.", "Redacción."], "herramientas": ["Una guía de conversación.", "Un editor de diagramas.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Mantén la neutralidad entre grupos y no tomes partido en conflictos locales."], "otroSector": "El mismo análisis sirve para mejorar la colaboración entre áreas de una organización."}$a54sld$::jsonb,64),
('identificando-las-necesidades-percibidas-por-una-comunidad','sociedad',array['ciudades']::text[],'Identificando las necesidades percibidas por una comunidad','Averigua qué necesidades dicen tener las personas de una comunidad, cuáles consideran más urgentes y qué soluciones imaginan, con una encuesta breve y conversaciones.','Investigación','3 semanas',22,array['Diagnóstico','Necesidades']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion diseno de encuestas. analisis de datos. comunicacion. redaccion. un formulario en linea. hoja de calculo. un editor de graficos.',$a55sld${"id": "identificando-las-necesidades-percibidas-por-una-comunidad", "area": "sociedad", "areas2": ["ciudades"], "titulo": "Identificando las necesidades percibidas por una comunidad", "resumen": "Averigua qué necesidades dicen tener las personas de una comunidad, cuáles consideran más urgentes y qué soluciones imaginan, con una encuesta breve y conversaciones.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Diagnóstico", "Necesidades"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Es común que las iniciativas empiecen con lo que otros creen que la comunidad necesita, y luego no funcionan porque no coinciden con las prioridades de la gente. Escuchar primero evita desperdiciar esfuerzos.", "Un diagnóstico de necesidades percibidas es el punto de partida de cualquier proyecto."], "desarrollar": ["Diseña una encuesta anónima de diez preguntas sobre necesidades, prioridades y soluciones imaginadas, y aplícala a 30 o más personas con consentimiento. Complementa con tres a cinco conversaciones voluntarias.", "Resume las necesidades en un ranking, compara por grupos, diferencia lo urgente de lo importante y devuelve los resultados a la comunidad con una hoja breve."], "ampliaciones": [{"titulo": "Necesidades vs deseos", "aporta": "distingue entre lo que se necesita y lo que se quiere."}, {"titulo": "Mapa de prioridades", "aporta": "ubica en un mapa dónde se sienten más las necesidades."}, {"titulo": "Devolución", "aporta": "organiza una reunión para compartir los resultados."}], "objetivos": ["Diseñar una encuesta de necesidades.", "Priorizar.", "Comparar por grupos.", "Devolver resultados."], "habilidades": ["Diseño de encuestas.", "Análisis de datos.", "Comunicación.", "Redacción."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir."], "otroSector": "El mismo diagnóstico sirve para conocer necesidades de clientes o de trabajadores."}$a55sld$::jsonb,65),
('que-significa-el-desarrollo-para-una-comunidad-construyendo-una','sociedad',array['educacion']::text[],'¿Qué significa el desarrollo para una comunidad? Construyendo una visión compartida para mejorarla','Diseña una dinámica para que los integrantes de una comunidad conversen sobre qué significa para ellos mejorar su vida y construyan una visión común, con metas y primeros pasos.','Plan','4 semanas',26,array['Desarrollo','Visión compartida']::text[],array['crear','investigar']::text[],'ficticios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion facilitacion. sintesis. planificacion. comunicacion. papelografo o pizarra. un editor de documentos. un grupo voluntario.',$a56sld${"id": "que-significa-el-desarrollo-para-una-comunidad-construyendo-una", "area": "sociedad", "areas2": ["educacion"], "titulo": "¿Qué significa el desarrollo para una comunidad? Construyendo una visión compartida para mejorarla", "resumen": "Diseña una dinámica para que los integrantes de una comunidad conversen sobre qué significa para ellos mejorar su vida y construyan una visión común, con metas y primeros pasos.", "tipo": "Plan", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Desarrollo", "Visión compartida"], "intencion": ["crear", "investigar"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["El desarrollo se entiende de distintas maneras: para unos es tener más ingresos, para otros más seguridad, para otros conservar sus costumbres. Si no se conversa, los proyectos se imponen desde una sola idea y no logran apoyo.", "Construir una visión compartida ayuda a que la comunidad decida hacia dónde quiere ir."], "desarrollar": ["Diseña un taller de dos a tres horas con preguntas guía, como cómo sería nuestro barrio ideal en cinco años, qué tenemos hoy y qué falta. Incluye dinámicas para que participen todas las edades y reglas de respeto. Prepara materiales y hoja de registro.", "Prueba el taller con un grupo de ocho a diez voluntarios, sintetiza las ideas en una visión de una página con tres metas y primeros pasos, y devuelve el resultado al grupo para que lo valide."], "ampliaciones": [{"titulo": "Indicadores de bienestar", "aporta": "propón cómo saber si se avanza hacia la visión."}, {"titulo": "Contrastar con datos", "aporta": "compara la visión con estadísticas de la zona."}, {"titulo": "Seguimiento", "aporta": "diseña revisiones cada seis meses."}], "objetivos": ["Diseñar el taller.", "Recoger ideas de distintos grupos.", "Sintetizar una visión.", "Validarla con la comunidad."], "habilidades": ["Facilitación.", "Síntesis.", "Planificación.", "Comunicación."], "herramientas": ["Papelógrafo o pizarra.", "Un editor de documentos.", "Un grupo voluntario."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Presenta la visión como un ejercicio de diálogo y no como un plan oficial."], "otroSector": "La misma dinámica sirve para definir la visión de un equipo o de una organización."}$a56sld$::jsonb,66),
('como-contar-una-causa-social-sin-victimizar-ni-exagerar','sociedad',array['arte']::text[],'Cómo contar una causa social sin victimizar ni exagerar','Aprende a presentar una causa social con respeto, sin mostrar a las personas como víctimas indefensas ni exagerar datos, y crea una guía con ejemplos de mensajes mal hechos y su versión mejorada.','Guía','3 a 4 semanas',24,array['Comunicación social','Ética']::text[],array['crear','investigar']::text[],'propios',NULL,'comunicaciones trabajo social sociologia diseno psicologia educacion antropologia ciencias politicas comunicacion etica. analisis critico. redaccion. diseno de materiales. ejemplos de campanas. un editor de diseno. un editor de documentos.',$a57sld${"id": "como-contar-una-causa-social-sin-victimizar-ni-exagerar", "area": "sociedad", "areas2": ["arte"], "titulo": "Cómo contar una causa social sin victimizar ni exagerar", "resumen": "Aprende a presentar una causa social con respeto, sin mostrar a las personas como víctimas indefensas ni exagerar datos, y crea una guía con ejemplos de mensajes mal hechos y su versión mejorada.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Comunicación social", "Ética"], "intencion": ["crear", "investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Comunicaciones", "Trabajo Social", "Sociología", "Diseño", "Psicología", "Educación", "Antropología", "Ciencias Políticas"], "problema": ["Para pedir apoyo, muchas campañas recurren a imágenes y frases que muestran a las personas como indefensas o exageran cifras. Eso puede conseguir donaciones rápidas, pero daña la dignidad de quienes aparecen y confunde a la gente sobre el problema real.", "Contar una causa con honestidad y respeto es posible y suele generar compromiso más duradero."], "desarrollar": ["Reúne diez mensajes de campañas sociales, en abstracto o con ejemplos ficticios, y analiza qué recursos usan: imágenes, adjetivos, cifras y llamados a la acción. Identifica cuáles pueden victimizar, exagerar o presentar datos sin fuente.", "Elabora una guía con criterios, como dar voz a las personas, usar datos verificables y mostrar capacidades y no solo carencias, y reescribe tres mensajes con esos criterios. Diseña una pieza de comunicación de ejemplo para una causa ficticia."], "ampliaciones": [{"titulo": "Fotos y consentimiento", "aporta": "elabora una guía para usar imágenes con respeto."}, {"titulo": "Lenguaje", "aporta": "arma un glosario de palabras que conviene evitar y alternativas."}, {"titulo": "Medir el efecto", "aporta": "prueba dos versiones de un mensaje con un grupo pequeño."}], "objetivos": ["Analizar mensajes de campañas.", "Definir criterios éticos.", "Reescribir mensajes.", "Diseñar una pieza de ejemplo."], "habilidades": ["Comunicación ética.", "Análisis crítico.", "Redacción.", "Diseño de materiales."], "herramientas": ["Ejemplos de campañas.", "Un editor de diseño.", "Un editor de documentos."], "lineamientos": ["Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Usa causas y casos ficticios, no uses fotos de personas reales sin su consentimiento y verifica cualquier dato que cites."], "otroSector": "La misma guía sirve para comunicación de organizaciones de salud, ambiente o derechos."}$a57sld$::jsonb,67),
('grupos-de-whatsapp-de-vecinos-o-de-clase-que-los-hace-utiles-y-q','sociedad',array['tecnologia']::text[],'Grupos de WhatsApp de vecinos o de clase: ¿qué los hace útiles y qué los vuelve ruido?','Analiza qué hace que un grupo de WhatsApp de vecinos o de clase sea útil o un ruido constante, con una encuesta anónima, y propone reglas simples para que funcione mejor.','Investigación','3 semanas',22,array['Comunicación grupal','Grupos de chat']::text[],array['investigar','crear']::text[],'propios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion diseno de encuestas. analisis de datos. comunicacion. facilitacion. un formulario en linea. hoja de calculo. un editor de documentos.',$a58sld${"id": "grupos-de-whatsapp-de-vecinos-o-de-clase-que-los-hace-utiles-y-q", "area": "sociedad", "areas2": ["tecnologia"], "titulo": "Grupos de WhatsApp de vecinos o de clase: ¿qué los hace útiles y qué los vuelve ruido?", "resumen": "Analiza qué hace que un grupo de WhatsApp de vecinos o de clase sea útil o un ruido constante, con una encuesta anónima, y propone reglas simples para que funcione mejor.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Comunicación grupal", "Grupos de chat"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Casi todos pertenecemos a algún grupo de chat de vecinos, de clase o de trabajo. Algunos sirven para avisar y coordinar; otros se llenan de cadenas, discusiones y mensajes irrelevantes que hacen que la gente los silencie.", "Entender qué los hace útiles permite acordar reglas y hacer que sirvan para lo que se crearon."], "desarrollar": ["Diseña una encuesta anónima sobre cuántos grupos tienen, para qué sirven, qué tipo de mensajes les parecen útiles o molestos y cuántos silencian. Aplícala a 30 o más personas con consentimiento.", "Analiza los resultados por tipo de grupo, identifica los patrones que vuelven un grupo ruidoso y redacta una propuesta de diez reglas simples, como horarios, temas permitidos y roles. Pruébala con un grupo que acepte y mide cambios."], "ampliaciones": [{"titulo": "Información importante", "aporta": "propón cómo evitar que lo urgente se pierda entre mensajes."}, {"titulo": "Alternativas", "aporta": "compara con avisos, tableros o correos."}, {"titulo": "Desinformación", "aporta": "analiza cómo circulan rumores en estos grupos."}], "objetivos": ["Diseñar una encuesta anónima.", "Identificar patrones de utilidad y ruido.", "Proponer reglas.", "Probarlas."], "habilidades": ["Diseño de encuestas.", "Análisis de datos.", "Comunicación.", "Facilitación."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Analiza el funcionamiento del grupo sin leer ni copiar conversaciones privadas de otras personas.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema."], "otroSector": "El mismo análisis sirve para canales de comunicación de equipos de trabajo."}$a58sld$::jsonb,68)
